  'COM_CONVERTFORMS_EXCEL_SECURITY' => 'Excel Security',
  'COM_CONVERTFORMS_EXCEL_SECURITY_DESC' => 'If enabled, values in the CSV exported file starting with a =, +, - or @ will be prefixed by a tab to avoid any CSV injection when opening the exported file using Excel. <br><br>Disable this option only if you are 100% certain that the data are trustworth or if you\'re facing difficulties importing the CSV file to a 3rd party application.',
  'COM_CONVERTFORMS_CHOICE_LAYOUT' => 'Choice Layout',
  'COM_CONVERTFORMS_CHOICE_LAYOUT_DESC' => 'Select the layout for displaying field choices',
  'COM_CONVERTFORMS_CHOICE_1_COLUMN' => 'One Column',
  'COM_CONVERTFORMS_CHOICE_2_COLUMN' => 'Two Columns',
